def expand_reviews(reviews):
    expanded = {}
    for name, original in reviews.items():
        sentences = original.split('. ')
        if name == 'Mariela Orellana Jaldín':
            paragraphs = original.replace(' En Química,', '\n\nEn Química,')
        else:
            cut = 2 if len(sentences) > 2 else 1
            paragraphs = '. '.join(sentences[:cut]) + '.\n\n' + '. '.join(sentences[cut:])
        expanded[name] = paragraphs + '\n\n' + ADDITIONS[name]
    expanded.update(ROLE_PROFILES)
    return expanded
